CREATE COLUMN TABLE "TEST_AP"."DTP1" ("Code" NVARCHAR(15) NOT NULL , "Level" INTEGER CS_INT NOT NULL , "Base" NVARCHAR(3) DEFAULT 'APC', "Years" INTEGER CS_INT, "Percentage" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0, "Amount" DECIMAL(21,6) CS_FIXED, "SnapshotId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("Code", "Level")) UNLOAD PRIORITY 5  AUTO MERGE 